<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Password Strength Meter</title>
    <style>
        #strength-meter {
            width: 300px;
            height: 20px;
            background-color: #eee;
            border: 1px solid #ccc;
        }
        #strength-label {
            margin-top: 10px;
        }
    </style>
</head>
<body>
    <h1>Password Strength Meter</h1>
    <input type="password" id="password-input" placeholder="Enter your password">
    <div id="strength-meter"></div>
    <p id="strength-label">Password Strength: Weak</p>

    <script>
        const passwordInput = document.getElementById('password-input');
        const strengthMeter = document.getElementById('strength-meter');
        const strengthLabel = document.getElementById('strength-label');

        function updateStrength(password) {
            let score = 0;
            if (password.length >= 8) score += 1;
            if (/[a-z]/.test(password)) score += 1;
            if (/[A-Z]/.test(password)) score += 1;
            if (/\d/.test(password)) score += 1;
            if (/[^a-zA-Z0-9]/.test(password)) score += 1;

            const strength = Math.min(score * 20, 100);
            strengthMeter.style.backgroundColor = `hsl(${strength}, 100%, 50%)`;
            strengthLabel.textContent = `Password Strength: ${score >= 4 ? 'Strong' : 'Weak'}`;
        }

        passwordInput.addEventListener('input', (event) => {
            updateStrength(event.target.value);
        });
    </script>
</body>
</html>
